1	// TypeScript-driven asset-loop orchestrator (thin slice).
2	//
3	// Owns one end-to-end pass: resolve asset → one in-memory Pi SDK session that
4	// writes component.html/.css (initial-gen) → one Playwright render → one
5	// critic call → write critique.json. No iteration, no fix loop, no accepted.json
6	// in this slice — those land in CP2.
7	
8	import { readFileSync, writeFileSync } from "node:fs";
9	
10	import { getModel } from "@mariozechner/pi-ai";
11	import {
12	  AuthStorage,
13	  createAgentSession,
14	  DefaultResourceLoader,
15	  getAgentDir,
16	  ModelRegistry,
17	  SessionManager,
18	} from "@mariozechner/pi-coding-agent";
19	
20	import { resolveAsset, type ResolvedAsset, type ResolveInput } from "./args.ts";
21	import { runCritique, type CritiqueIssue } from "./critic.ts";
22	import { runFixStep } from "./fixStep.ts";
23	import { readPngSize } from "./pngSize.ts";
24	import { renderWithPlaywright } from "./renderer.ts";
25	import { buildSystemPrompt } from "./systemPrompt.ts";
26	import { AssetLoopTUI } from "./tui.ts";
27	import { UsageAggregator, formatUsageSnapshot } from "./usage.ts";
28	import { buildRenderWrapper } from "./wrapper.ts";
29	
30	const MODEL_PROVIDER = "anthropic" as const;
31	const MODEL_ID = "claude-opus-4-7" as const;
32	const MAX_ITERATIONS = 15;
33	
34	function writeAcceptedJson(
35	  resolved: ResolvedAsset,
36	  payload: {
37	    iterations: number;
38	    hitEmpty: boolean;
39	    residualIssues: CritiqueIssue[];
40	    verdict: string;
41	  },
42	): void {
43	  const notes: string[] = payload.hitEmpty
44	    ? [`converged at iteration ${payload.iterations}`]
45	    : [
46	        `iteration cap reached at ${payload.iterations} renders`,
47	        `${payload.residualIssues.length} residual issue(s)`,
48	      ];
49	  const output = {
50	    asset_id: resolved.assetId,
51	    iterations: payload.iterations,
52	    max_iterations: MAX_ITERATIONS,
53	    hit_empty_issues: payload.hitEmpty,
54	    residual_issues: payload.residualIssues,
55	    verdict: payload.verdict,
56	    notes,
57	    accepted_at: new Date().toISOString(),
58	  };
59	  writeFileSync(resolved.acceptedJsonPath, `${JSON.stringify(output, null, 2)}\n`);
60	}
61	
62	export async function runAssetLoop(input: ResolveInput): Promise<void> {
63	  const resolved = resolveAsset(input);
64	  const usage = new UsageAggregator();
65	
66	  const referenceBuf = readFileSync(resolved.extractedPngPath);
67	  const { width: referenceWidth, height: referenceHeight } = readPngSize(referenceBuf);
68	  const referenceBase64 = referenceBuf.toString("base64");
69	  const sourceBase64 = readFileSync(resolved.sourcePngPath).toString("base64");
70	  const assetJsonText = readFileSync(resolved.assetJsonPath, "utf8");
71	  const extractionPromptText = readFileSync(resolved.extractionPromptPath, "utf8");
72	
73	  const tui = new AssetLoopTUI({
74	    assetId: resolved.assetId,
75	    maxIterations: MAX_ITERATIONS,
76	    extractedBase64: referenceBase64,
77	    extractedMime: "image/png",
78	  });
79	  tui.start();
80	  tui.setPhase("initial_gen");
81	
82	  const sigintHandler = () => {
83	    try {
84	      tui.stop();
85	    } finally {
86	      process.exit(130);
87	    }
88	  };
89	  process.once("SIGINT", sigintHandler);
90	
91	  try {
92	  const authStorage = AuthStorage.create();
93	  const modelRegistry = ModelRegistry.create(authStorage);
94	
95	  const model = getModel(MODEL_PROVIDER, MODEL_ID);
96	  if (!model) {
97	    throw new Error(`Model not found: ${MODEL_PROVIDER}/${MODEL_ID}`);
98	  }
99	
100	  const systemPrompt = buildSystemPrompt({
101	    assetId: resolved.assetId,
102	    assetDir: resolved.assetDir,
103	    assetJson: assetJsonText,
104	    referenceWidth,
105	    referenceHeight,
106	  });
107	
108	  const agentDir = getAgentDir();
109	  const resourceLoader = new DefaultResourceLoader({
110	    cwd: resolved.assetDir,
111	    agentDir,
112	    systemPromptOverride: () => systemPrompt,
113	  });
114	  await resourceLoader.reload();
115	
116	  const { session } = await createAgentSession({
117	    cwd: resolved.assetDir,
118	    agentDir,
119	    model,
120	    thinkingLevel: "high",
121	    authStorage,
122	    modelRegistry,
123	    resourceLoader,
124	    sessionManager: SessionManager.inMemory(),
125	  });
126	
127	  session.subscribe((event) => {
128	    if (
129	      event.type === "message_end" &&
130	      event.message?.role === "assistant" &&
131	      event.message.usage
132	    ) {
133	      usage.add(event.message.usage);
134	      tui.setUsage(usage.snapshot());
135	    }
136	  });
137	
138	  const kickoffText = [
139	    `Context for asset "${resolved.assetId}". Four inputs follow: source screenshot (ground truth in situ), extracted asset (native ${referenceWidth}x${referenceHeight}px; your primary render target), the extraction prompt that produced the extracted asset, and asset metadata (already in the system prompt). Read all four before writing code.`,
140	    "",
141	    "Extraction prompt that produced the extracted image:",
142	    "",
143	    extractionPromptText.trim(),
144	    "",
145	    "Source screenshot (ground truth in situ) first, extracted asset (primary render target) second.",
146	  ].join("\n");
147	
148	  console.log("phase: initial-gen");
149	  await session.prompt(kickoffText, {
150	    images: [
151	      { type: "image", data: sourceBase64, mimeType: "image/png" },
152	      { type: "image", data: referenceBase64, mimeType: "image/png" },
153	    ],
154	  });
155	  await session.agent.waitForIdle();
156	  session.dispose();
157	
158	  for (let iteration = 1; iteration <= MAX_ITERATIONS; iteration++) {
159	    tui.setIteration(iteration);
160	    tui.setPhase("render");
161	    console.log(`phase: render iter ${iteration}/${MAX_ITERATIONS}`);
162	    const componentHtml = readFileSync(resolved.componentHtmlPath, "utf8");
163	    const componentCss = readFileSync(resolved.componentCssPath, "utf8");
164	    writeFileSync(resolved.wrapperPath, buildRenderWrapper(componentHtml, componentCss));
165	    await renderWithPlaywright({
166	      wrapperPath: resolved.wrapperPath,
167	      renderPath: resolved.renderPath,
168	      referenceWidth,
169	      referenceHeight,
170	    });
171	    const renderBase64 = readFileSync(resolved.renderPath).toString("base64");
172	    tui.setRender(renderBase64, "image/png");
173	    tui.setPhase("critique");
174	
175	    console.log(`phase: critique iter ${iteration}`);
176	    const auth = await modelRegistry.getApiKeyAndHeaders(model);
177	    if (!auth.ok) {
178	      throw new Error(`Cannot resolve credentials for critic: ${auth.error}`);
179	    }
180	    const outcome = await runCritique({
181	      model,
182	      auth: { apiKey: auth.apiKey, headers: auth.headers },
183	      sourcePngPath: resolved.sourcePngPath,
184	      extractedPngPath: resolved.extractedPngPath,
185	      renderPngPath: resolved.renderPath,
186	      extractionPromptText,
187	      assetJson: assetJsonText,
188	    });
189	    for (const u of outcome.usages) usage.add(u);
190	    tui.setUsage(usage.snapshot());
191	
192	    if (!outcome.ok) {
193	      console.error(
194	        `aborted: critic parse failure — ${truncate(outcome.rawSecond, 400)}`,
195	      );
196	      console.error(formatUsageSnapshot(usage.snapshot()));
197	      tui.stop();
198	      throw new Error("critic parse failure");
199	    }
200	
201	    writeFileSync(
202	      resolved.critiqueJsonPath,
203	      `${JSON.stringify({ iteration, verdict: outcome.result.verdict, issues: outcome.result.issues }, null, 2)}\n`,
204	    );
205	
206	    tui.setIssues(outcome.result.issues);
207	
208	    if (outcome.result.issues.length === 0) {
209	      console.log("accepted — hit_empty");
210	      writeAcceptedJson(resolved, {
211	        iterations: iteration,
212	        hitEmpty: true,
213	        residualIssues: [],
214	        verdict: outcome.result.verdict,
215	      });
216	      tui.setPhase("done");
217	      tui.showSummary([
218	        "hit_empty: true",
219	        `iter ${iteration}/${MAX_ITERATIONS}`,
220	        formatUsageSnapshot(usage.snapshot()),
221	        `accepted: ${resolved.acceptedJsonPath}`,
222	      ]);
223	      tui.stop();
224	      return;
225	    }
226	
227	    if (iteration === MAX_ITERATIONS) {
228	      console.log("accepted — cap");
229	      writeAcceptedJson(resolved, {
230	        iterations: iteration,
231	        hitEmpty: false,
232	        residualIssues: outcome.result.issues,
233	        verdict: outcome.result.verdict,
234	      });
235	      tui.setPhase("done");
236	      tui.showSummary([
237	        "cap_reached",
