1	// Resolves an asset dir produced by apps/asset-extraction-pipeline and finds
2	// the extracted reference image (structured path first, legacy root fallback).
3	
4	import { existsSync, readFileSync } from "node:fs";
5	import { isAbsolute, resolve } from "node:path";
6	
7	export interface ResolvedAsset {
8	  assetId: string;
9	  assetDir: string;
10	  assetJsonPath: string;
11	  extractedPngPath: string;
12	  sourcePngPath: string;
13	  extractionPromptPath: string;
14	  componentHtmlPath: string;
15	  componentCssPath: string;
16	  renderPath: string;
17	  wrapperPath: string;
18	  acceptedJsonPath: string;
19	  critiqueJsonPath: string;
20	}
21	
22	export interface ResolveInput {
23	  asset: string | undefined;
24	  run: string | undefined;
25	  cwd: string;
26	}
27	
28	export function resolveAsset(input: ResolveInput): ResolvedAsset {
29	  if (!input.asset) {
30	    throw new Error("--asset is required (path to asset dir or bare id with --run)");
31	  }
32	
33	  const assetDir = resolveAssetDir(input.asset, input.run, input.cwd);
34	  if (!existsSync(assetDir)) {
35	    throw new Error(`Asset dir not found: ${assetDir}`);
36	  }
37	
38	  const assetJsonPath = resolve(assetDir, "asset.json");
39	  if (!existsSync(assetJsonPath)) {
40	    throw new Error(`Missing asset metadata: ${assetJsonPath}`);
41	  }
42	
43	  const extractedPngPath = resolveExtractedPng(assetDir);
44	  const sourcePngPath = resolveSourcePng(assetDir);
45	  const extractionPromptPath = resolveExtractionPrompt(assetDir);
46	
47	  const assetId = parseAssetId(assetJsonPath) ?? assetDir.split("/").pop() ?? "asset";
48	
49	  return {
50	    assetId,
51	    assetDir,
52	    assetJsonPath,
53	    extractedPngPath,
54	    sourcePngPath,
55	    extractionPromptPath,
56	    componentHtmlPath: resolve(assetDir, "component.html"),
57	    componentCssPath: resolve(assetDir, "component.css"),
58	    renderPath: resolve(assetDir, "render.png"),
59	    wrapperPath: resolve(assetDir, "wrapper.html"),
60	    acceptedJsonPath: resolve(assetDir, "accepted.json"),
61	    critiqueJsonPath: resolve(assetDir, "critique.json"),
62	  };
63	}
64	
65	function resolveSourcePng(assetDir: string): string {
66	  const candidate = resolve(assetDir, "..", "..", "source.png");
67	  if (!existsSync(candidate)) {
68	    throw new Error(`Missing source screenshot: ${candidate}`);
69	  }
70	  return candidate;
71	}
72	
73	function resolveExtractionPrompt(assetDir: string): string {
74	  const candidate = resolve(assetDir, "extraction", "prompt_generation", "prompt.txt");
75	  if (!existsSync(candidate)) {
76	    throw new Error(`Missing extraction prompt: ${candidate}`);
77	  }
78	  return candidate;
79	}
80	
81	function resolveAssetDir(asset: string, run: string | undefined, cwd: string): string {
82	  const looksLikePath = asset.includes("/") || isAbsolute(asset) || existsSync(asset);
83	  if (looksLikePath) {
84	    return resolve(cwd, asset);
85	  }
86	  if (!run) {
87	    throw new Error(`--asset "${asset}" looks like a bare id; also pass --run <run-dir>`);
88	  }
89	  return resolve(cwd, run, "assets", asset);
90	}
91	
92	function resolveExtractedPng(assetDir: string): string {
93	  const structured = resolve(assetDir, "extraction", "image_extraction", "extracted.png");
94	  if (existsSync(structured)) return structured;
